INSERT INTO UNTACT_BOOK_RESERVATION
(
	homepage_id, locker_number, request_number, member_id, member_name,
	request_date, locker_password, reservation_step, reg_no, book_regno,
	book_isbn, book_name, loan_date, cancel_yn, cancel_reason,
	cancel_id, cancel_ip, sms_send_yn, sms_send_date
) VALUES (
	#{homepage_id}, #{locker_number}, #{request_number}, #{member_id}, #{member_name},
	TO_DATE(#{request_date},'yyyy-MM-dd HH24:MI:SS'), #{locker_password}, '예약', #{reg_no}, #{book_regno},
	#{book_isbn}, #{book_name}, #{loan_date}, 'N', #{cancel_reason},
	#{cancel_id}, #{cancel_ip}, #{sms_send_yn}, #{sms_send_date}
)

mapper.update:
UPDATE
	UNTACT_BOOK_RESERVATION
SET
	locker_type = #{locker_type}
WHERE
	homepage_id = #{homepage_id}
AND member_id = #{member_id}
AND reservation_step = #{reservation_step}
AND TO_CHAR(request_date, 'yyyy-MM-dd') = TO_CHAR(SYSDATE, 'yyyy-MM-dd')

UPDATE
	UNTACT_BOOK_RESERVATION
SET
	locker_password = #{locker_password}
WHERE
	homepage_id = #{homepage_id}
AND request_number = #{request_number}
AND cancel_yn = 'N'
AND TO_CHAR(request_date, 'yyyy-MM-dd') = TO_CHAR(SYSDATE, 'yyyy-MM-dd')

mapper.select:
${pagingTop}
	SELECT
		homepage_id, locker_number, request_number, member_id, member_name,
		TO_CHAR(request_date,'yyyy-MM-dd HH24:MI:SS') AS request_date, locker_password, reservation_step, reg_no, book_regno,
		book_isbn, book_name, loan_date, cancel_yn, cancel_reason,
		cancel_id, cancel_ip, sms_send_yn, sms_send_date
	FROM
		UNTACT_BOOK_RESERVATION
	WHERE
		homepage_id = #{homepage_id}
	AND member_id = #{member_id}
	ORDER BY request_number DESC
${pagingBottom}
